-- Message Catalog seed.
--
-- 1. Legacy language code ENG -> en (the app's locale codes). Two messages
--    exist as both ENG and en with identical text; the en copy (no
--    description) is dropped. If a pair ever differs, the UPDATE hits the
--    primary key and this migration fails rather than lose either text.
-- 2. The existing core messages, so fresh environments get the same
--    catalog (ON CONFLICT DO NOTHING: edits made through the catalog win).
-- 3. Set 9100 (the catalog's own messages) and Spanish/French for set 1
--    (the generic messages every unmapped error falls back to).

DELETE FROM public.message_catalog e
 WHERE e.language_cd = 'en'
   AND EXISTS (SELECT 1 FROM public.message_catalog g
                WHERE g.language_cd = 'ENG' AND g.set_nbr = e.set_nbr
                  AND g.message_nbr = e.message_nbr AND g.message_text = e.message_text);
UPDATE public.message_catalog SET language_cd = 'en' WHERE language_cd = 'ENG';
UPDATE public.tenant_message_catalog SET language_cd = 'en' WHERE language_cd = 'ENG';

ALTER TABLE public.message_catalog ALTER COLUMN language_cd SET DEFAULT 'en';
ALTER TABLE public.tenant_message_catalog ALTER COLUMN language_cd SET DEFAULT 'en';

ON CONFLICT (set_nbr) DO NOTHING;

ON CONFLICT (set_nbr, message_nbr, language_cd) DO NOTHING;

UPDATE public.message_catalog SET user_action = 'Quote the reference when you contact support; it identifies the exact failure.' WHERE set_nbr = 1 AND message_nbr = 4 AND language_cd = 'en' AND user_action IS NULL;
